CREATE TABLE IF NOT EXISTS lb_players (id TEXT PRIMARY KEY, key TEXT NOT NULL, board TEXT NOT NULL, gsub TEXT, name TEXT NOT NULL, av TEXT, pts INTEGER NOT NULL DEFAULT 0, w INTEGER NOT NULL DEFAULT 0, l INTEGER NOT NULL DEFAULT 0, best INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL, updated INTEGER NOT NULL); CREATE INDEX IF NOT EXISTS idx_lbp_rank ON lb_players (board, pts DESC, updated ASC); CREATE UNIQUE INDEX IF NOT EXISTS idx_lbp_google ON lb_players (board, gsub); CREATE TABLE IF NOT EXISTS lb_claims (mid TEXT NOT NULL, pid TEXT NOT NULL, opp TEXT, res TEXT, at INTEGER NOT NULL, PRIMARY KEY (mid, pid)); CREATE TABLE IF NOT EXISTS lb_settled (mid TEXT PRIMARY KEY, at INTEGER NOT NULL); CREATE TABLE IF NOT EXISTS lb_presence (sid TEXT PRIMARY KEY, board TEXT NOT NULL, state TEXT, at INTEGER NOT NULL); CREATE INDEX IF NOT EXISTS idx_pres ON lb_presence (board, at); CREATE TABLE IF NOT EXISTS lb_lobbies (code TEXT PRIMARY KEY, board TEXT NOT NULL, owner TEXT NOT NULL, ad TEXT NOT NULL, at INTEGER NOT NULL); DROP TABLE IF EXISTS submissions; DROP TABLE IF EXISTS players;
